from typing import Union


class SwStream:
    """ Represents BTS software stream. """

    def __init__(self, name: str):
        """
        :param name: software stream name, i.e. '26R1'.
        """
        self._name = name
        self._number = int(''.join([char for char in name if char.isdigit()]))

    def __str__(self) -> str:
        return self._name

    def __gt__(self, other: Union['SwStream', str]) -> bool:
        if isinstance(other, str):
            other = SwStream(name=other)
        return self._number > other.number

    def __ge__(self, other: Union['SwStream', str]) -> bool:
        if isinstance(other, str):
            other = SwStream(name=other)
        return self._number >= other.number

    def __lt__(self, other: Union['SwStream', str]) -> bool:
        if isinstance(other, str):
            other = SwStream(name=other)
        return self._number < other.number

    def __le__(self, other: Union['SwStream', str]) -> bool:
        if isinstance(other, str):
            other = SwStream(name=other)
        return self._number <= other.number

    def __eq__(self, other: Union['SwStream', str]) -> bool:
        if isinstance(other, str):
            other = SwStream(name=other)
        return self._number == other.number

    def __ne__(self, other: Union['SwStream', str]) -> bool:
        if isinstance(other, str):
            other = SwStream(name=other)
        return self._number != other.number

    @property
    def number(self) -> int:
        """ Returns software stream converted into number, i.e. for '26R1' returns 261. """
        return self._number
